<?php
declare(strict_types=1); namespace App\DataGrid\Csv; use App\DataGrid\Configuration\GridDefinition; use App\DataGrid\Contract\GridExportDataProviderInterface; use App\DataGrid\Dto\GridQuery; use Symfony\Bundle\SecurityBundle\Security; use Symfony\Component\HttpFoundation\StreamedResponse; final class CsvExporter {public function export(GridExportDataProviderInterface $p,GridDefinition $d,GridQuery $q,Security $s,string $name):StreamedResponse{$cols=array_values(array_filter($d->visibleColumns($s),fn($c)=>$c->exportable));$r=new StreamedResponse(function()use($p,$d,$q,$s,$cols){$o=fopen('php://output','wb');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,array_map(fn($c)=>$c->label,$cols),';');foreach($p->iterateGridRows($d,$q,$s)as$row){fputcsv($o,array_map(fn($c)=>$this->safe($row[$c->id]??null),$cols),';');}fclose($o);});$r->headers->set('Content-Type','text/csv; charset=UTF-8');$r->headers->set('Content-Disposition','attachment; filename="'.preg_replace('/[^a-zA-Z0-9._-]/','_',$name).'.csv"');return$r;} private function safe(mixed $v):string{$v=is_array($v)?implode(', ',array_map('strval',$v)):(is_bool($v)?($v?'Oui':'Non'):(string)$v);return preg_match('/^[=+\-@]/u',$v)?"'".$v:$v;}}
